let markdownModule;
async function markdown(text){if(!markdownModule)markdownModule=import('/static/vendor/marked.esm.js');const {marked}=await markdownModule;const template=document.createElement('template');template.innerHTML=marked.parse(String(text||''),{gfm:true,breaks:true});const allowed=new Set(['P','BR','STRONG','EM','DEL','H1','H2','H3','H4','H5','H6','UL','OL','LI','BLOCKQUOTE','PRE','CODE','TABLE','THEAD','TBODY','TR','TH','TD','HR','A','IMG']);for(const el of [...template.content.querySelectorAll('*')]){if(!allowed.has(el.tagName)){el.remove();continue;}const href=el.getAttribute('href'),src=el.getAttribute('src'),alt=el.getAttribute('alt');for(const a of [...el.attributes])el.removeAttribute(a.name);if(el.tagName==='A'&&href){try{const u=new URL(href,location.origin);if(['http:','https:'].includes(u.protocol)){el.href=u.href;el.target='_blank';el.rel='noopener noreferrer';}}catch{}}if(el.tagName==='IMG'&&src){try{const u=new URL(src,location.origin);if(u.origin===location.origin&&u.pathname.startsWith('/api/projects/')){el.src=u.href;el.alt=alt||'';el.loading='lazy';}else el.remove();}catch{el.remove();}}}return template.innerHTML;}
function latestPlan(){return A.task?.plans?.at(-1);}
function profileHTML(profile){if(!profile?.files?.length)return '';const roles={taxonomy:'物种丰度表',metadata:'样本信息表',functional:'功能丰度表',table:'普通表格',results:'已有结果表'};return `<details class="v2-data-profile" open><summary>已识别 ${profile.files.length} 份数据</summary><table><thead><tr><th>文件</th><th>类型</th><th>规模</th></tr></thead><tbody>${profile.files.map(f=>`<tr><td>${esc(f.filename)}</td><td>${esc(f.stratified_only?'物种分层通路表':roles[f.role]||f.role)}</td><td>${f.rows} 行 · ${f.columns} 列 · ${f.sample_count} 个样本</td></tr>`).join('')}</tbody></table>${profile.files.some(f=>f.stratified_only)?'<p>功能表仅有物种分层贡献，未包含群落总通路丰度。</p>':''}${profile.alignments.some(a=>!a.exact_matches)?'<p>部分文件的样本编号尚未直接对应；跨表分析前需要确认匹配规则。</p>':''}</details>`;}
const generationFailed=p=>p.generation_failed||p.status==='planning_failed';
function planBubble(){const plans=A.task?.plans||[];if(!plans.length)return '';A.planIndex=Math.max(0,Math.min(A.planIndex<0?plans.length-1:A.planIndex,plans.length-1));const p=plans[A.planIndex],run=(A.task.runs||[]).find(r=>r.plan_id===p.id);return `<article class="v2-message v2-assistant v2-plan"><header><h2>分析方案 · V${p.revision}</h2><span>${generationFailed(p)?'方案生成失败':p.status==='needs_input'?'待补充信息':run?'已确认':'待确认'}</span></header>${profileHTML(p.data_profile||A.task.data_profile)}${p.resolved_context?.defaults?.length?`<p class="v2-defaults">${p.resolved_context.defaults.map(esc).join("；")}</p>`:""}${p.resolved_context?.group_column?`<p class="v2-binding">已绑定分组：${esc(p.resolved_context.group_column)}${p.resolved_context.group_values?.length?` · ${p.resolved_context.group_values.map(esc).join(" / ")}`:""}</p>`:""}<p>${esc(generationFailed(p)?'上一版方案未通过流程检查，尚未执行。可以基于已读取的数据重新生成。':p.summary||A.task.messages.find(m=>m.role==='user'&&m.type==='text')?.text||p.objective.split('后续修订要求：')[0].replace(/^初始研究目标：\s*/,''))}</p>${(generationFailed(p)?[]:p.questions||[]).map(q=>`<p class="v2-plan-question">${esc(typeof q==='string'?q:JSON.stringify(q))}</p>`).join('')}<ol>${p.steps.map(s=>`<li><strong>${esc(A.tools.find(t=>t.id===s.skill)?.name||s.skill)}</strong><p>${esc(s.reason||'')}</p>${s.skill==='custom_analysis'&&s.program?`<details><summary>方法与验收要求</summary><p>${esc(s.program.method)}</p><p>样本编号：${s.program.sample_alignment==='canonical'?'按确认的主键规则一对一规范化，并保存映射记录。':'保留原始编号并精确匹配。'}</p><ul>${(s.program.requirements||[]).map(r=>`<li>${esc(r.description)}</li>`).join('')}</ul><p>预期输出：${(s.program.outputs||[]).map(o=>esc(o.title)).join('、')}</p></details>`:''}</li>`).join('')}</ol><div class="v2-plan-footer">${generationFailed(p)?button('重新生成方案','v2-replan','class="primary"'):button(run?'已确认执行':'确认并执行','v2-confirm',`data-id="${p.id}" ${run||p.status!=='ready'?'disabled':''} class="primary"`)}<div>${button('‹','v2-plan-page',`data-delta="-1" ${A.planIndex===0?'disabled':''} aria-label="上一版方案"`)}<span>${A.planIndex+1} / ${plans.length}</span>${button('›','v2-plan-page',`data-delta="1" ${A.planIndex===plans.length-1?'disabled':''} aria-label="下一版方案"`)}</div></div></article>`;}
async function reportBubble(run){const key=run.id;let report=A.reports.get(key);if(!report){report=await api(taskURL('/report/'+run.id));A.reports.set(key,report);}if(report.interpretation_source!=='ai_evidence_summary'&&!A.reportPending.has(key)){A.reportPending.add(key);const tid=A.task.id;api(taskURL('/report/'+run.id),'POST',{}).then(result=>{A.reports.set(key,result);if(A.task?.id===tid&&A.tab==='agent'){const host=root.querySelector('[data-v2-report="'+key+'"]');if(host)markdown(result.markdown).then(html=>host.innerHTML=html);}}).catch(()=>{});}return `<article class="v2-message v2-assistant v2-report"><header><h2>分析报告</h2>${button('下载报告','v2-download-report',`data-id="${run.id}"`)}</header><div class="v2-markdown" data-v2-report="${run.id}">${await markdown(report.markdown)}</div></article>`;}
async function conversation(){await tools();const t=A.task,planMessage=[...t.messages].reverse().find(m=>m.type==='plan'),parts=[];for(const m of t.messages){if(m.type==='text')parts.push(`<article class="v2-message ${m.role==='user'?'v2-user':'v2-assistant'}">${esc(m.text).replace(/\n/g,'<br>')}</article>`);else if(m.type==='plan'){if(m.id===planMessage?.id)parts.push(planBubble());else{const p=t.plans.find(p=>p.id===m.plan_id);parts.push(`<p class="v2-version-note">已生成方案 V${p?.revision||1}</p>`);}}else if(m.type==='run'){const run=t.runs.find(r=>r.id===m.run_id);if(!run)continue;if(['queued','running','cancelling'].includes(run.status))parts.push(`<article class="v2-message v2-assistant v2-running"><header><h2>运行记录</h2><span>${esc(labels[run.status]||run.status)}</span></header><progress max="${run.progress.total||1}" value="${run.progress.completed}"></progress><p>已完成 ${run.progress.completed} / ${run.progress.total} 步</p>${button('取消运行','v2-cancel-run',`data-id="${run.id}"`)}</article>`);else{if(run.error)parts.push(`<article class="v2-message v2-assistant"><h2>${esc(labels[run.status]||run.status)}</h2><p>${esc(run.error)}</p>${run.needs_plan_confirmation?'<p>请在下方说明方案修改要求，确认新版方案后再执行。</p>':button('恢复执行','v2-resume-run',`data-id="${run.id}"`)}</article>`);parts.push(await reportBubble(run));}}}
if(t.status==='planning')parts.push('<article class="v2-message v2-assistant v2-thinking" role="status">正在设计方案…</article>');return `<div class="v2-conversation">${parts.join('')||(t.data_profile?.files?.length?'<article class="v2-message v2-assistant">'+profileHTML(t.data_profile)+'<p>文件已读取，可以继续说明你的分析目标。</p></article>':'<div class="v2-task-empty">描述分析目标，或先添加数据。</div>')}</div><div class="v2-chat-input">${composer(true)}</div>`;}
forms['v2-message']=async f=>{if(A.attachBusy)throw Error('文件正在关联，请稍候');const text=f.elements.message.value.trim();if(!text)return;A.text=text;A.sending=true;try{await ensureTask();const tid=A.task.id,pid=A.task.project_id;A.text='';state.page='home';A.tab='agent';const promise=api(taskURL('/messages'),'POST',{text,skills:[...A.skills]}).then(detail=>({detail}),error=>({error}));await fetchTask();await render();const reply=await promise;if(reply.error)throw reply.error;const detail=reply.detail;if(A.task?.id===tid&&state.project===pid){A.task=detail;A.planIndex=-1;await render();await tree(true);}}finally{A.sending=false;const submit=root.querySelector('[data-form="v2-message"] [type="submit"]');if(submit){submit.disabled=false;submit.innerHTML=active()?svg('send',21):'AI 设计方案';}}};
actions['v2-replan']=async()=>{const form=root.querySelector('[data-form="v2-message"]');form.elements.message.value='根据已读取的数据和原始研究目标，修正上一版方案并重新生成。';await forms['v2-message'](form);};
actions['v2-plan-page']=async e=>{A.planIndex+=Number(e.dataset.delta);await render();};
