actions['v2-download-report']=e=>{const r=A.reports.get(e.dataset.id);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([r.markdown],{type:'text/markdown;charset=utf-8'}));a.download=(A.task.title||'分析报告')+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
views.assets=async()=>{if(!active())return old.assets();await fetchTask();context();const data=await api(url('/library-browser?task_id='+id(window.BioFlowTaskContext.libraryId)+'&kind=data'));const any=Object.values(data.counts).some(n=>n>0);if(A.upload||!any){const html=await old.data();const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.section-head')?.remove();return taskShell(`<div class="v2-data-heading"><h2>上传分析数据</h2>${any?button('返回文件列表','v2-data-list'):''}</div>`+t.innerHTML);}const html=await old.assets();const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.catalogue-view-bar')?.remove();const upload=t.content.querySelector('[data-action="library-upload"]');if(upload&&state.assetKind==='data')upload.textContent='上传数据';return taskShell(t.innerHTML);};
